import sys


def calc(expr: str) -> int | str:
    # Tokenize
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(int(expr[i:j]))
            i = j
        elif c in "+-*/%^()":
            tokens.append(c)
            i += 1
        else:
            i += 1

    class EvaluationError(Exception):
        pass

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return None

    def consume():
        nonlocal pos
        t = tokens[pos]
        pos += 1
        return t

    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise EvaluationError()
        sign = -1 if (a < 0) ^ (b < 0) else 1
        return sign * (abs(a) // abs(b))

    def trunc_mod(a: int, b: int) -> int:
        if b == 0:
            raise EvaluationError()
        d = trunc_div(a, b)
        return a - b * d

    def int_pow(a: int, b: int) -> int:
        if b < 0:
            raise EvaluationError()
        if b == 0:
            return 1
        return pow(a, b)

    # Grammar based on precedence:
    # expr -> term_add
    # term_add -> term_mul ( ('+' | '-') term_mul )*
    # term_mul -> term_unary ( ('*' | '/' | '%') term_unary )*
    # term_unary -> '-' term_unary | term_pow
    # term_pow -> primary ( '^' term_unary )?
    # primary -> NUMBER | '(' expr ')'

    def parse_expr() -> int:
        val = parse_term_mul()
        while peek() in ("+", "-"):
            op = consume()
            rhs = parse_term_mul()
            if op == "+":
                val += rhs
            else:
                val -= rhs
        return val

    def parse_term_mul() -> int:
        val = parse_term_unary()
        while peek() in ("*", "/", "%"):
            op = consume()
            rhs = parse_term_unary()
            if op == "*":
                val *= rhs
            elif op == "/":
                val = trunc_div(val, rhs)
            elif op == "%":
                val = trunc_mod(val, rhs)
        return val

    def parse_term_unary() -> int:
        if peek() == "-":
            consume()
            return -parse_term_unary()
        return parse_term_pow()

    def parse_term_pow() -> int:
        base = parse_primary()
        if peek() == "^":
            consume()
            # Right-associative; right operand can start with unary minus: e.g. 2^-1, 2^3^2
            exp = parse_term_unary()
            return int_pow(base, exp)
        return base

    def parse_primary() -> int:
        t = consume()
        if isinstance(t, int):
            return t
        elif t == "(":
            val = parse_expr()
            consume()  # ')'
            return val
        raise EvaluationError()

    old_limit = sys.getrecursionlimit()
    try:
        sys.setrecursionlimit(max(old_limit, len(tokens) + 100))
        res = parse_expr()
        return res
    except EvaluationError:
        return "error"
    finally:
        sys.setrecursionlimit(old_limit)
